import{_ as r,o,c as n,ae as s}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"架构师-备考 综合知识-架构设计-架构设计方法","description":"","frontmatter":{"title":"架构师-备考 综合知识-架构设计-架构设计方法"},"headers":[],"relativePath":"综合知识/架构设计/架构设计方法.md","filePath":"综合知识/架构设计/架构设计方法.md"}'),l={name:"综合知识/架构设计/架构设计方法.md"};function i(a,t,g,d,e,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] ABSD（基于架构的软件设计）— 六个子过程</li><li>[x] DSSA（特定领域软件架构）— 领域分析/设计/实现</li><li>[x] 4+1 视图模型</li><li>[x] 架构文档化</li><li>[x] 软件架构复用（机会复用/系统复用/水平式/垂直式）</li><li>[x] 架构复审与演化</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、absd-—-基于架构的软件设计" tabindex="-1">一、ABSD — 基于架构的软件设计 <a class="header-anchor" href="#一、absd-—-基于架构的软件设计" aria-label="Permalink to &quot;一、ABSD — 基于架构的软件设计&quot;">​</a></h3><blockquote><p>ABSD 方法是由<strong>商业、质量和功能需求</strong>的组合驱动的，是一个<strong>自顶向下、递归细化</strong>的方法，直到能产生<strong>软件构件和类</strong>。</p></blockquote><p><strong>ABSD 方法的三个基础：</strong></p><ol><li>对系统进行功能分解</li><li>采用<strong>架构策略</strong>实现质量属性与商业需求</li><li>采用软件模板设计软件结构</li></ol><p><strong>六个子过程：</strong></p><ol><li><strong>架构需求</strong> — 获取需求</li><li><strong>架构设计</strong> — 设计方案</li><li><strong>架构文档化</strong> — 输出架构规格说明和测试架构需求的质量设计说明书</li><li><strong>架构复审</strong> — 标识潜在风险，及早发现架构设计中的缺陷和错误</li><li><strong>架构实现</strong> — 编码实现</li><li><strong>架构演化</strong> — 应对需求变化，修改应用架构满足新需求</li></ol><hr><h3 id="二、dssa-—-特定领域软件架构" tabindex="-1">二、DSSA — 特定领域软件架构 <a class="header-anchor" href="#二、dssa-—-特定领域软件架构" aria-label="Permalink to &quot;二、DSSA — 特定领域软件架构&quot;">​</a></h3><blockquote><p>DSSA 是特定应用领域中为一组应用提供组织结构参考的<strong>标准软件架构</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>产出</th></tr></thead><tbody><tr><td><strong>领域分析</strong></td><td>获得<strong>领域模型</strong>，描述领域中系统间的共同需求</td><td>领域模型</td></tr><tr><td><strong>领域设计</strong></td><td>获得<strong>特定领域软件架构（DSSA）</strong></td><td>领域架构</td></tr><tr><td><strong>领域实现</strong></td><td>开发和组织可重用信息，实现基础软件架构</td><td>可重用构件/资产</td></tr></tbody></table><p><strong>四类参与角色：</strong></p><ol><li><strong>领域专家</strong> — 提供领域知识</li><li><strong>领域分析者</strong> — 控制领域分析过程，进行知识获取，组织领域模型</li><li><strong>领域设计者</strong> — 根据领域模型开发领域设计，验证设计的准确性和一致性</li><li><strong>领域实现者</strong> — 实现可重用资产</li></ol><p><strong>DSSA 三级层次：</strong></p><ul><li>领域开发环境 → <strong>应用工程师</strong>主要在领域特定应用开发环境中工作</li><li>领域特定应用开发环境</li><li>应用执行环境</li></ul><p><strong>垂直域 vs 水平域：</strong></p><ul><li><strong>垂直域</strong>：定义了一个特定的系统族，包含整个系统族内的多个系统</li><li><strong>水平域</strong>：定义了多个系统和多个系统族中功能区域的共有部分，在子系统级上涵盖多个系统族</li></ul><hr><h3 id="三、4-1-视图模型" tabindex="-1">三、4+1 视图模型 <a class="header-anchor" href="#三、4-1-视图模型" aria-label="Permalink to &quot;三、4+1 视图模型&quot;">​</a></h3><blockquote><p>4+1 视图模型从多个视图描述软件体系结构，核心思想是<strong>关注点分离</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>视图</th><th>作用</th><th>关注点</th></tr></thead><tbody><tr><td><strong>逻辑视图</strong></td><td>描述对象模型，说明系统应提供哪些服务</td><td>功能需求（用户视角）</td></tr><tr><td><strong>过程视图</strong></td><td>捕捉设计的<strong>并发和同步</strong>特性</td><td>系统行为特性（动态视角）</td></tr><tr><td><strong>开发视图</strong></td><td>描述开发环境中软件的<strong>静态组织结构</strong></td><td>模块组织</td></tr><tr><td><strong>物理视图</strong></td><td>描述软件到硬件的映射</td><td>部署拓扑</td></tr><tr><td><strong>场景（+1）</strong></td><td><strong>用例视图</strong>，验证其他视图一致性</td><td>统一场景</td></tr></tbody></table><p><strong>视图与视角关系：</strong></p><ul><li><strong>静态视角</strong>（展示功能组织）→ 判断质量特性</li><li><strong>动态视角</strong>（展示并发行为）→ 判断系统行为特性</li><li>四个视图：逻辑视图、进程视图、实现视图、<strong>配置视图</strong></li><li>使用<strong>逻辑视图</strong>记录设计元素的功能和概念接口</li></ul><hr><h3 id="四、架构文档化" tabindex="-1">四、架构文档化 <a class="header-anchor" href="#四、架构文档化" aria-label="Permalink to &quot;四、架构文档化&quot;">​</a></h3><blockquote><p>架构文档化过程的主要输出结果是<strong>架构规格说明书</strong>和<strong>测试架构需求的质量设计说明书</strong>。</p></blockquote><p><strong>文档化原则：</strong></p><ul><li>从使用者的角度书写文档</li><li>随时保证文档是最新的</li><li>将文档分发给相关人员</li><li>针对不同背景的人员书写文档的方式不同</li></ul><hr><h3 id="五、软件复用" tabindex="-1">五、软件复用 <a class="header-anchor" href="#五、软件复用" aria-label="Permalink to &quot;五、软件复用&quot;">​</a></h3><p><strong>机会复用 vs 系统复用：</strong></p><ul><li><strong>机会复用</strong>（发现复用）：开发过程中，只要发现有可复用的资产，就进行复用</li><li><strong>系统复用</strong>（计划复用）：开发之前就进行规划，决定哪些需要复用</li></ul><p><strong>水平式重用 vs 垂直式重用：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>典型代表</th></tr></thead><tbody><tr><td><strong>水平式重用</strong></td><td>跨领域通用（应用领域无关），提供基础功能</td><td>标准函数库、通用类库</td></tr><tr><td><strong>垂直式重用</strong></td><td>面向特定领域（领域相关），包含领域知识</td><td>医学词汇表、电子商务标准、网银支付接口</td></tr></tbody></table><p><strong>复用过程的三个主要阶段：</strong></p><ol><li>构造/获取可复用的软件资产</li><li>管理可复用资产</li><li>使用可复用资产</li></ol><hr><h3 id="六、架构复审与演化" tabindex="-1">六、架构复审与演化 <a class="header-anchor" href="#六、架构复审与演化" aria-label="Permalink to &quot;六、架构复审与演化&quot;">​</a></h3><p><strong>架构复审目的：</strong> 标识潜在风险，及早发现架构设计中的缺陷和错误。复审过程中主要由<strong>用户代表与领域专家</strong>决定架构是否满足需求、质量需求是否在设计中得到体现。</p><p><strong>架构演化：</strong> 针对用户需求变化，修改应用架构满足新的需求。</p><p><strong>架构描述与需求对应：</strong></p><ul><li>架构 → 用<strong>视角与视图</strong>描述</li><li>功能需求 → 用<strong>用例</strong>描述</li><li>质量需求 → 用<strong>质量场景</strong>描述</li></ul>',44)])])}const b=r(l,[["render",i]]);export{u as __pageData,b as default};
